import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    // After clarifying: return indices, exactly one answer, or an empty array if none
    static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>(); // value -> index
        for (int i = 0; i < nums.length; i++) {
            int need = target - nums[i];
            if (seen.containsKey(need)) return new int[] { seen.get(need), i };
            seen.put(nums[i], i);
        }
        return new int[0];
    }

    public static void main(String[] args) { // test out loud
        System.out.println(Arrays.toString(twoSum(new int[] { 2, 7, 11, 15 }, 9))); // [0, 1]
        System.out.println(Arrays.toString(twoSum(new int[] { 3, 3 }, 6))); // [0, 1]
        System.out.println(Arrays.toString(twoSum(new int[] { -4, 1, 9 }, 5))); // [0, 2]
        System.out.println(Arrays.toString(twoSum(new int[] { 1, 2 }, 7))); // []
    }
}
